export function dossierSha16(dossierMd: string, originJson: string): string {
  const mdDigest = createHash("sha256").update("dossier.md", "utf8").update(dossierMd, "utf8").digest("hex");
  const originDigest = createHash("sha256").update("origin.json", "utf8").update(originJson, "utf8").digest("hex");
  return createHash("sha256").update(mxDigest, "utf8").update(originDigest, "utf8")
    .digest("hex").slice(0, 16);
}

