export async function syncPrs(db: Database, list: () => Promise<PrRow[]>): Promise<{ rows: number }> {
  let rows: PrRow[];
  try {
    rows = await list();
  } catch (err) {
    throw new Error(`Failed to list PRs for sync: ${err instanceof Error ? err.message : String(err)}`);
  }
  try {
    const tx = db.transaction(() => { for (const r of rows) upsertPr(db, r); });
    tx();
  } catch (err) {
    throw new Error(`Failed to upsert PRs into pr_node: ${err instanceof Error ? err.message : String(err)}`);
  }
  return { rows: rows.length };
}

